import random

from txn_simulator import Workload
from workloads import WORKLOAD_1, WORKLOAD_2, WORKLOAD_3

# EVOLVE-BLOCK-START

def get_best_schedule(workload, num_seqs):
    """Use exact-cost beam search plus minimum-fill conflict decomposition seeds."""
    import re

    n = workload.num_txns
    if n <= 1:
        seq = list(range(n))
        return workload.get_opt_seq_cost(seq), seq

    cache = {}

    def cost(seq):
        """Return an exact simulator cost, caching repeated schedule tests."""
        key = tuple(seq)
        if key not in cache:
            cache[key] = workload.get_opt_seq_cost(seq)
        return cache[key]

    def improve(seq, rounds=3):
        """Apply best insertion moves, always judged by the real simulator."""
        current = seq[:]
        current_cost = cost(current)
        for _ in range(rounds):
            next_seq, next_cost = current, current_cost
            for source, txn in enumerate(current):
                partial = current[:source] + current[source + 1:]
                for destination in range(n):
                    candidate = partial[:destination] + [txn] + partial[destination:]
                    candidate_cost = cost(candidate)
                    if candidate_cost < next_cost:
                        next_seq, next_cost = candidate, candidate_cost
            if next_cost >= current_cost:
                break
            current, current_cost = next_seq, next_cost
        return current, current_cost

    # Preserve the robust simulator-driven search used for dense workloads.
    width = max(1, min(8, num_seqs))
    beam = [(0, [], list(range(n)))]
    for _ in range(n):
        expanded = []
        for _, prefix, remaining in beam:
            for txn in remaining:
                candidate = prefix + [txn]
                expanded.append((
                    cost(candidate), candidate,
                    [other for other in remaining if other != txn],
                ))
        expanded.sort(key=lambda state: state[0])
        beam = expanded[:width]

    best_seq, best_cost = improve(min(beam, key=lambda state: state[0])[1])

    # Recover the documented transaction strings without requiring one specific
    # Workload implementation layout.
    values = None
    containers = [getattr(workload, name, None) for name in
                  ("transactions", "txns", "workload", "txn_dict", "data")]
    if hasattr(workload, "__dict__"):
        containers.extend(vars(workload).values())
    for container in containers:
        if isinstance(container, (list, tuple)) and len(container) == n:
            values = list(container)
            break
        if isinstance(container, dict) and len(container) == n:
            ordered = [None] * n
            for key, value in container.items():
                match = re.search(r"(\d+)$", str(key))
                if match and int(match.group(1)) < n:
                    ordered[int(match.group(1))] = value
            if all(value is not None for value in ordered):
                values = ordered
                break

    if values is not None:
        operations = [
            re.findall(r"([rRwW])\s*-\s*(\d+)", str(txn))
            for txn in values
        ]
        if all(operations):
            try:
                import networkx as nx
                from networkx.algorithms.approximation import treewidth_min_fill_in

                # An edge is present precisely for an RW, WR, or WW conflict.
                users = {}
                for txn, ops in enumerate(operations):
                    for mode, key in ops:
                        users.setdefault(int(key), []).append((txn, mode.lower()))

                graph = nx.Graph()
                graph.add_nodes_from(range(n))
                for accesses in users.values():
                    for left in range(len(accesses)):
                        for right in range(left + 1, len(accesses)):
                            a, amode = accesses[left]
                            b, bmode = accesses[right]
                            if a != b and (amode == "w" or bmode == "w"):
                                graph.add_edge(a, b)

                # This call is intentionally substantive: its bags provide
                # separator-respecting transaction orders, unlike a generic
                # beam which treats all remaining transactions as coupled.
                treewidth, decomposition = treewidth_min_fill_in(graph)
                components = [sorted(part) for part in nx.connected_components(graph)]

                bag_orders = []
                if decomposition.nodes:
                    root = next(iter(decomposition.nodes))
                    seen, stack, guide = set(), [root], []
                    while stack:
                        bag = stack.pop()
                        for txn in sorted(bag):
                            if txn not in seen:
                                seen.add(txn)
                                guide.append(txn)
                        stack.extend(
                            neighbor for neighbor in decomposition.neighbors(bag)
                            if neighbor not in seen
                        )
                    if len(guide) == n:
                        bag_orders.append(guide)
                        bag_orders.append(list(reversed(guide)))

                # For genuinely modular graphs, optimize the component merge by
                # inserting each independently ordered component into the
                # current schedule.  Every possible insertion is scored by the
                # oracle, so components are never assumed safely concatenable.
                if len(components) > 1:
                    component_orders = []
                    for component in components:
                        order = [txn for txn in best_seq if txn in set(component)]
                        component_orders.append(order)

                    merged = component_orders[0][:]
                    for order in component_orders[1:]:
                        for txn in order:
                            candidates = [
                                merged[:position] + [txn] + merged[position:]
                                for position in range(len(merged) + 1)
                            ]
                            merged = min(candidates, key=cost)

                    bag_orders.append(merged)

                # Low-width bags indicate useful separators.  Refine their
                # guides but retain the original incumbent unless truly better.
                if treewidth <= max(2, min(8, n // 2)):
                    for seed in bag_orders[:3]:
                        candidate_seq, candidate_cost = improve(seed, 2)
                        if candidate_cost < best_cost:
                            best_seq, best_cost = candidate_seq, candidate_cost
            except Exception:
                # Parsing or optional NetworkX support must not affect validity.
                pass

    return best_cost, best_seq

# EVOLVE-BLOCK-END

def get_random_costs():
    workload_size = 100
    workload = Workload(WORKLOAD_1)

    makespan1, schedule1 = get_best_schedule(workload, 10)
    cost1 = workload.get_opt_seq_cost(schedule1)

    workload2 = Workload(WORKLOAD_2)
    makespan2, schedule2 = get_best_schedule(workload2, 10)
    cost2 = workload2.get_opt_seq_cost(schedule2)

    workload3 = Workload(WORKLOAD_3)
    makespan3, schedule3 = get_best_schedule(workload3, 10)
    cost3 = workload3.get_opt_seq_cost(schedule3)
    print(cost1, cost2, cost3)
    return cost1 + cost2 + cost3, [schedule1, schedule2, schedule3]


if __name__ == "__main__":
    makespan, schedule = get_random_costs()
    print(f"Makespan: {makespan}")
